def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    if frequency != '5 minutes':
        raise ValueError('This skill requires 5-minute frequency data')
    window = 12  # 12 * 5-minute intervals = 1 hour
    if len(history) < window:
        raise ValueError(f'History must contain at least {window} observations')
    avg = sum(history[-window:]) / window
    return [avg] * horizon

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    if frequency != '1 minute':
        raise ValueError('This skill requires 1-minute frequency data')
    window_size = min(60, len(history)) if len(history) > 0 else 0
    avg = sum(history[-window_size:]) / window_size if window_size > 0 else 0.0
    return [avg] * horizon
